import { useFeatureFlag } from "./index.js";
import { useNoInteractiveChildren } from "../../internal/useNoInteractiveChildren.js";
//#region src/components/FeatureFlags/useNoInteractiveChildrenForLabel.ts
/**
* Warn about interactive label content in v11 and enforce it in v12.
*/
const useNoInteractiveChildrenForLabel = (ref, message) => {
	const enableV12Release = useFeatureFlag("enable-v12-release");
	const migrationMessage = `${message}. Render interactive content as a sibling of the label or use the \`decorator\` prop when available`;
	useNoInteractiveChildren(ref, migrationMessage, { shouldThrow: enableV12Release });
};
//#endregion
export { useNoInteractiveChildrenForLabel };
